m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C0498')
R=[dict(id='C0498',meaning='迈步；台阶；等级',core='一次迈出一步；把连续变化看作一阶一阶',image='沿台阶向前、向后、向上或跨越边界，分别形成进展、退回、升级和越界。',intro='拉丁 gradus 是“一步、台阶、等级”，gradī / gradior 是“走、迈步”。身体迈步可以变成事情推进；台阶的高低又变成等级、学位和刻度。它不只表示缓慢：gradual 才突出一步步，progress 本身不限定速度。',forms='grad- 常保留台阶或等级画面；复合动词中可见 -gred-，过去分词及相关名词常见 -gress-。因此 progress、regress、transgress 与 grade 虽然拼写不同，仍能接上“走”的来源。',branches=[['一步步推进','progress、gradual、gradually'],['等级与资格','grade、degree、graduate、graduation'],['上升或降低','upgrade、downgrade、degrade'],['往回或越界','regress、retrograde、transgress'],['专业方向','anterograde、antegrade、prograde'],['沉积与步态','aggradation、progradation、tardigrade、saltigrade']],contrasts='progress 不总是好转；degradable 不自动等于 biodegradable。grade 是等级，gradient 是坡度或梯度。gree 的同意义另属 grātus，不能因为拼写接近就混成同源。',practice='用三个画面复述：走到下一步是 progress；向下调档是 downgrade；跨过界线是 transgress。再区分 graduate 的名词 /uət/ 与动词 /ueɪt/，并用一句话说明毕业 graduation 与渐变 gradation 的差别。',words=list(family),sources=['https://www.etymonline.com/word/grade','https://www.etymonline.com/word/progress','https://www.etymonline.com/word/gradation'])]
assert {w['word'] for w in W}==set(family)-{'aggression'}
assert len(W)==50
for w in W:
 assert len(w['examples'])>=2 and len(w['history'])>=2 and w['ipa'],w['word']
 assert all(len(n)==2 and all(isinstance(v,str) and v for v in n) for n in w['history']),w['word']
OUT.mkdir(parents=True,exist_ok=True)
for k,d in [('roots',R),('words',W)]: (OUT/f'{k}_batch200_spec_07_grad.json').write_text(json.dumps(d,ensure_ascii=False,indent=2))
print('C0498',len(W),'new',sum(len(w['examples']) for w in W),'examples')
